import {tailOptions} from './options.js';
import {clothingOptions} from './clothing-options.js';
import {accessoryOptions,accessorySelected} from './accessories.js';
const keys={syringe:'syringeColor',clothing:'clothingColor',sleepCap:'sleepCapColor',spaceHelmet:'spaceHelmetColor',guitar:'guitarColor',burger:'burgerColor',laptop:'laptopColor',tail:'tailColor',halo:'haloColor',horns:'hornsColor',glasses:'glassesColor',headset:'headsetColor',hat:'hatColor',ribbon:'ribbonColor',hairClip:'clipColor',earrings:'earringColor',neckAccessory:'neckColor',bodyCostume:'pumpkinColor',mug:'mugColor',tufts:'tuftColor'};
let api,signature='',selected='';
export function initAccessoryControls(value){api=value;document.querySelector('#panel-accessory').insertAdjacentHTML('afterbegin','<section class="active-accessory-tools"><div class="control-heading"><h3>착용한 소품 색상</h3><span>누르면 바로 변경</span></div><div id="active-accessory-colors" class="active-color-grid"></div><details id="accessory-position" class="advanced-section"><summary>소품 위치와 크기 조절<span>＋</span></summary><div class="advanced-body"><label class="advanced-field"><span>조절할 소품</span><select id="position-accessory" aria-label="위치를 조절할 소품"></select></label><div id="accessory-position-controls"></div></div></details></section>');document.querySelector('#position-accessory').addEventListener('change',e=>{selected=e.target.value;syncAccessoryControls(api.getState(),true);});}
export function syncAccessoryControls(s,force=false){
 if(!api)return;const active=accessoryOptions.filter(a=>accessorySelected(s,a));if(s.tail!=='none')active.push({id:'tail-'+s.tail,key:'tail',label:tailOptions.find(([id])=>id===s.tail)?.[1]??'꼬리'});if(s.clothing!=='none')active.push({id:'clothing-'+s.clothing,key:'clothing',label:clothingOptions.find(([id])=>id===s.clothing)?.[1]??'옷'});const next=active.map(a=>a.id).join('|');
 if(next!==signature||force){signature=next;const colors=document.querySelector('#active-accessory-colors');colors.innerHTML=active.length?active.map(a=>{const key=a.key==='wings'?(a.value==='angel'?'angelWingColor':'devilWingColor'):a.key==='bodyCostume'&&a.value==='burger'?'burgerColor':a.key==='hat'&&a.styleValue==='candyBasket'?'basketColor':keys[a.key];return `<label class="accessory-color-card"><span>${a.label}</span><input type="color" data-active-color="${key}" data-accessory-key="${a.key}" aria-label="${a.label} 색상"></label>`;}).join(''):'<p class="panel-note">소품을 선택하면 색상과 위치를 여기서 조절할 수 있어요.</p>';
  colors.querySelectorAll('[data-active-color]').forEach(el=>{el.setAttribute('aria-label',el.previousElementSibling.textContent+' 색상');api.bindControl(el,()=>({[el.dataset.activeColor]:el.value,...(el.dataset.accessoryKey==='tufts'?{tuftSeparate:true}:el.dataset.accessoryKey==='tail'?{tailSeparate:true}:{})}));});
  if(!active.some(a=>a.key===selected))selected=active[0]?.key??'';const select=document.querySelector('#position-accessory');select.innerHTML=active.map(a=>`<option value="${a.key}">${a.label}</option>`).join('');select.value=selected;
  document.querySelector('#accessory-position').hidden=!active.length;
  const controls=document.querySelector('#accessory-position-controls');controls.innerHTML=selected?[['x','좌우',-3,3,.01,0],['y','높이',-3,3,.01,0],['z','앞뒤',-3,3,.01,0],['scale','크기',.2,3,.01,1],['angle','기울기',-180,180,1,0],...(['earrings','horns','wings'].includes(selected)||selected==='ribbon'&&s.ribbon==='both'||selected==='hairClip'&&['bar','cross'].includes(s.hairClip)?[['gap','짝 사이 간격',-1.2,2,.01,0]]:[])].map(([key,label,min,max,step])=>`<label class="advanced-field range-field"><span>${label}<output data-accessory-output="${key}"></output></span><input type="range" data-accessory-transform="${key}" min="${min}" max="${max}" step="${step}" aria-label="소품 ${label}"></label>`).join('')+'<button id="reset-accessory-position" class="text-button">이 소품의 위치와 크기 복원</button>':'';
  controls.querySelectorAll('[data-accessory-transform]').forEach(el=>api.bindControl(el,()=>{const s=api.getState();return{accessoryTransforms:{...s.accessoryTransforms,[selected]:{...s.accessoryTransforms[selected],[el.dataset.accessoryTransform]:Number(el.value)}}};}));document.querySelector('#reset-accessory-position')?.addEventListener('click',()=>{const t={...api.getState().accessoryTransforms};delete t[selected];api.change({accessoryTransforms:t});});
 }
 document.querySelectorAll('[data-active-color]').forEach(el=>el.value=s[el.dataset.activeColor]);const t=s.accessoryTransforms[selected]??{};document.querySelectorAll('[data-accessory-transform]').forEach(el=>{const key=el.dataset.accessoryTransform,value=t[key]??(key==='scale'?1:0);el.value=value;el.style.setProperty('--fill',`${(value-el.min)/(el.max-el.min)*100}%`);document.querySelector(`[data-accessory-output="${key}"]`).textContent=key==='angle'?`${value}°`:Number(value).toFixed(2);});
}
